public class LibraryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Library lib = new Library();
        check("empty library count", 0, lib.count());
        check("empty library longestTitle", "", lib.longestTitle());
        check("empty library hasTitle", false, lib.hasTitle("Dune"));

        lib.addTitle("Dune");
        lib.addTitle("The Left Hand of Darkness");
        lib.addTitle("Hyperion");
        check("count after three adds", 3, lib.count());
        check("hasTitle exact case", true, lib.hasTitle("Dune"));
        check("hasTitle ignores case", true, lib.hasTitle("dUNE"));
        check("hasTitle for missing book", false, lib.hasTitle("Foundation"));
        check("longestTitle", "The Left Hand of Darkness", lib.longestTitle());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

